"use client";

import MainLayout from "@/layouts/MainLayout";

import Navbar from "@/components/Navbar";

import { useAssignmentStore } from "@/store/useAssignmentStore";

export default function PreviewPage() {
  const { generatedPaper } = useAssignmentStore();

  return (
    <MainLayout>
      <Navbar />

      <div className="bg-white rounded-3xl mt-5 p-10 max-w-5xl mx-auto">
        <div className="text-center">
          <h1 className="text-5xl font-bold">Delhi Public School</h1>

          <p className="text-2xl mt-3">Science Question Paper</p>
        </div>

        <div className="mt-12 space-y-3">
          <p>Name: __________________</p>

          <p>Roll Number: __________________</p>

          <p>Section: __________________</p>
        </div>

        <div className="mt-16">
          {generatedPaper.map((section, sectionIndex) => (
            <div key={sectionIndex} className="mb-14">
              <h2 className="text-3xl font-bold">{section.title}</h2>

              <p className="text-gray-500 mt-2">{section.instruction}</p>

              <div className="mt-8 space-y-8">
                {section.questions.map((question, questionIndex) => (
                  <div key={questionIndex} className="border rounded-2xl p-5">
                    <div className="flex justify-between items-start gap-5">
                      <p className="text-lg">
                        {questionIndex + 1}. {question.text}
                      </p>

                      <div className="flex gap-3">
                        <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-sm">
                          {question.difficulty}
                        </span>

                        <span className="bg-black text-white px-3 py-1 rounded-full text-sm">
                          {question.marks} Marks
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </MainLayout>
  );
}
